"""Admission and forwarding for native iterator conveniences; no execution loops."""
MD = 'Movable & Deinitable'
START = '# --- iterator expansion syntax (generated) ---\n'
END = '# --- end iterator expansion syntax ---\n'
HEADER = '# Generated by scripts/generate_plain_overloads.py; algorithms live in the operation owners.\n'

PARAMS = {'T':'The source element type, including origins.', 'A':'The first callback argument type.', 'B':'The second callback argument type.', 'R':'The callback result type.', 'F':'The concrete callback type, preserving captures and receiver semantics.', 'C':'The borrowing callback type.', 'V':'The consumed native iterator or owned collection type.', 'W':'The second consumed source type.', 'o':'The origin of the borrowed callback or comparison value.', 'E':'The exact native callback error type; generic forwarders pass E=E.', 'M':'The explicit Monoid; identity and combination retain its error type.', 'S':'The explicit Semigroup; no identity value is required.', 'Ss':'The additional source types; an iterator keeps its current position.', 'predicate':'The non-raising compile-time thin predicate.'}
ARGS = {'source':'The source, consumed at its current position.', 'other':'The second source, consumed at its current position.', 'others':'Additional sources, consumed without restarting iterators.', 'function':'The callback; lazy operations own it and terminals borrow native callbacks or consume library callables.', 'predicate':'The predicate, borrowing each candidate; lazy operations own it and terminals borrow native callbacks or consume library callables.', 'value':'The comparison value, borrowed for the duration of the terminal.', 'n':'The native take/drop count; non-positive counts retain standard behavior.', 'start':'The first native Int index; defaults to zero.'}

def emit(name,params,args,result,condition,body,summary,details='',error=None,indent='',docs=True):
    p='['+', '.join(params)+']' if params else ''
    s=f'\n{indent}def {name}{p}({", ".join(args)})'
    if error: s+=f' raises {error}'
    s+=f' -> {result}'
    if condition:s+=' where '+condition
    s+=':\n'+indent+'    """'+summary+'\n'
    if docs:
        if details:s+='\n'+''.join(indent+'    '+line+'\n' for line in details.splitlines())
        named=[v.split(':',1)[0].lstrip('*') for v in params if v!='//']
        if named:
            s+='\n'+indent+'    Parameters:\n'
            s+=''.join(indent+'        '+n+': '+PARAMS.get(n, 'The admitted type parameter.')+'\n' for n in named)
        named=[v.split(':',1)[0].split()[-1].lstrip('*') for v in args if ':' in v]
        if named:
            s+='\n'+indent+'    Args:\n'+''.join(indent+'        '+n+': '+ARGS.get(n,'The operation argument.')+'\n' for n in named)
        s+='\n'+indent+'    Returns:\n'+indent+'        '+result+' with the ownership, timing and empty-input behavior described above.\n'
        if error:s+='\n'+indent+'    Raises:\n'+indent+'        The exact admitted callback or combination error; Never when non-raising.\n'
    s+=indent+'    """\n'+''.join(indent+'    '+x+'\n' for x in body.splitlines())
    return s

def prefixes(mode):
    out=''
    for name,taking in [('take_while',True),('drop_while',False)]:
        desc='Yield the initial matching prefix; consume and discard its first rejection.' if taking else 'Discard the matching prefix; yield the first rejection and stop testing.'
        for kind in ['thin','native','library']:
            params=[f'T: {MD}'] if kind!='library' else ['C: BorrowCallable']
            if mode=='free':params += [f'V: {MD}']
            cb='C' if kind=='library' else 'def(T) thin -> Bool' if kind=='thin' else 'F'
            if kind=='native': params+=['//', 'F: _LazyPredicate[T]']
            t=f'downcast[C.Payload, {MD}]' if kind=='library' else 'T'
            it='_Source[V]' if mode=='free' else 'Self.I'
            condition=it+'.Element == '+t
            if kind=='library':condition+=' and C.Result == Bool and C.Failure == Never'
            args=['var predicate: '+cb]+(['var source: V'] if mode=='free' else [])
            result=f'{"Take" if taking else "Drop"}WhileIterator[{t}, {it}, {cb}]'
            call=f'_Prefix[{t}, {it}, {cb}, {taking}](predicate{"" if kind=="thin" else "^"}, _source(source^), True, False)' if mode=='free' else f'_{name}(predicate{"" if kind=="thin" else "^"}, self._iterator^)'
            if mode!='free':args.insert(0,'deinit self'); result=f'Iter[{result}]';call=f'Iter({call})'
            out+=emit(name,params,args,result,condition,'return '+call,desc,'Construction pulls nothing. The stored predicate borrows each candidate and cannot raise.\nExhaustion is fused; abandonment releases captures and the unconsumed source.\nUses constant state and preserves move-only elements and embedded origins.',indent='' if mode=='free' else '    ',docs=kind=='thin')
    return out

def indexed(mode):
    out=''
    for name in ['zip_with','map_with_index']:
        for kind in ['thin','native','library']:
            iszip=name=='zip_with'; params=([f'A: {MD}',f'B: {MD}',f'R: {MD}'] if iszip else [f'T: {MD}',f'R: {MD}']) if kind!='library' else [f'F: BinaryContract & {MD}']
            a='A' if iszip else 'Int'; b='B' if iszip else 'T';r='R'
            if kind=='library':a='F.First' if iszip else 'Int';b='F.Second';r='F.Out'
            cb=f'def(var {a}, var {b}) thin -> {r}' if kind=='thin' else 'F'
            if mode=='free':params+=[f'V: {MD}']
            if iszip:params+=[f'W: {MD}']
            if kind=='native':params+=['//',f'F: _Binary[{a}, {b}, R]' if iszip else 'F: _IndexedBinary[T, R]']
            it='_Source[V]' if mode=='free' else 'Self.I'
            condition=f'{it}.Element == '+(a if iszip else b)
            if iszip:condition+=f' and _Source[W].Element == {b}'
            if kind=='library':condition+=' and F.Error == Never and RepeatableBinary[F]'+(' and F.First == Int' if not iszip else '')
            args=['var function: '+cb]
            if mode=='free':args+=['var source: V']
            if iszip:args+=['var other: W']
            else:args+=['*','start: Int = 0']
            result=f'ZipWithIterator[{a}, {b}, {r}, {it}, _Source[W], {cb}]' if iszip else f'IndexedMapIterator[{b}, {r}, {it}, {cb}]'
            if mode=='free':
                body='var source_iter = '+('_native_zip(source^, other^)' if iszip else '_enumerate(_OwnedSource(source^), start=start)')+'\n'
                body+=f'return {result}(function{"" if kind=="thin" else "^"}, source_iter^, False)'
            else:
                args.insert(0,'deinit self')
                # Fluent zip takes the peer before the callback.
                if iszip:args=['deinit self','var other: W','var function: '+cb]
                result='Iter['+result+']'
                body='return Iter(_'+name+'(function'+('' if kind=='thin' else '^')+', self._iterator^'+(', other^)' if iszip else ', start=start)')+')'
            summary='Lazily combine pairs using native left-to-right zip followed by map.' if iszip else 'Lazily map (index, owned element), using native enumerate then map.'
            out+=emit(name,params,args,result,condition,body,summary,'Construction is inert; each output moves its inputs into the non-raising callback.\n'+('Native zip can consume an earlier input before a later one ends.\n' if iszip else '')+'Mapping fuses exhaustion and retains owned captures, move-only results and native origins.',indent='' if mode=='free' else '    ',docs=kind=='thin')
    return out

def native_methods():
    out=''
    for name,typ in [('take','_TakeIterator'),('drop','_DropIterator')]:
        out+=emit(name,[],['deinit self','n: Int'],f'Iter[{typ}[Self.I]]','conforms_to(Self.I.Element, Deinitable)' if name=='drop' else '',f'return Iter(_std_{name}(_OwnedSource(self._iterator^), n))',f'Apply native {name} without restarting the source.','Construction pulls nothing; non-positive counts retain standard semantics.\nBounds and exhaustion delegate unchanged to the native adapter.',indent='    ')
    out+=emit('enumerate',[],['deinit self','*','start: Int = 0'],'Iter[_Enumerate[Self.I]]','', 'return Iter(_std_enumerate(_OwnedSource(self._iterator^), start=start))','Lazily attach native (index, value) pairs, starting at start.','The source keeps its current position; construction pulls nothing.\nBounds and exhaustion remain native.',indent='    ')
    for name in ['zip','chain']:
        typ='_ZipIterator[MutUntrackedOrigin, *_NativeTail[Self.I, *Ss]]' if name=='zip' else '_ChainedIterator[*_NativeTail[Self.I, *Ss]]'
        cond='' if name=='zip' else 'TypeList[Trait=Movable & Deinitable, Ss.values]().all[_SameSource[Self.I.Element, _]]()'
        out+=emit(name,[f'*Ss: {MD}'],['deinit self','var *others: *Ss'],f'Iter[{typ}]',cond,f'return Iter(_native_{name}(self._iterator^, *others^))','Combine the remaining sources through native '+name+'.','Sources are consumed once and never restarted. Zip yields flat tuples,\nstopping at the shortest input; earlier inputs may be pulled before a later\ninput ends. Chain yields same-typed elements in source order. Construction\npulls nothing; native bounds, ownership and exhaustion remain unchanged.',indent='    ')
    for name,typ in [('take_while','_TakeWhileIterator'),('drop_while','_DropWhileIterator')]:
        out+=emit(name,['predicate: def(Self.I.Element) thin -> Bool'],['deinit self'],f'Iter[{typ}[InnerIteratorType=Self.I, predicate=predicate]]','conforms_to(Self.I.Element, Deinitable)',f'return Iter(_std_{name}[predicate=predicate](_OwnedSource(self._iterator^)))','Apply native '+name+' with a compile-time thin predicate.','Construction pulls nothing. Take consumes the first rejected candidate;\ndrop yields it and stops testing. Bounds and exhaustion remain native.\nUse the value-taking overload for an owned closure or library predicate.',indent='    ')
    return out

def terminals(mode):
    out='';ind='' if mode=='free' else '    ';src='source^' if mode=='free' else 'self._iterator^';it='_Source[V]' if mode=='free' else 'Self.I'
    for name in ['first','last','is_empty','count','contains','to_non_empty_list','combine_all_optional']:
        params=[];args=['var source: V'] if mode=='free' else ['deinit self'];cond=''
        if name=='contains':params=[f'T: Equatable & {MD}','o: ImmOrigin'];args+=['ref[o] value: T'];t='T';cond=it+'.Element == T and conforms_to('+it+'.Element, Movable & Deinitable)'
        elif name=='combine_all_optional':params=['S: Semigroup'];t='S.Value';cond=it+'.Element == S.Value'
        else:t=f'downcast[{it}.Element, {MD}]';cond=f'conforms_to({it}.Element, Deinitable)'
        if mode=='free':params+=[f'V: {MD}']
        result={'first':f'Optional[{t}]','last':f'Optional[{t}]','is_empty':'Bool','count':'Int','contains':'Bool','to_non_empty_list':f'Optional[NonEmptyList[{t}]]','combine_all_optional':f'Optional[{t}]'}[name]
        error='S.Error' if name=='combine_all_optional' else None
        if mode=='iter':body='return _'+name+('[S=S]' if name=='combine_all_optional' else '')+f'({src}'+(', value)' if name=='contains' else ')')
        elif name=='first':body='return _source(source^).nth(0)'
        elif name=='is_empty':body='return not first(source^)'
        elif name=='contains':body='return _any(_EqualTo[T, o](Pointer(to=value)), source^)'
        elif name=='to_non_empty_list':body=f'return NonEmptyList[{t}].from_list(collect_list[T={t}](source^))'
        elif name=='combine_all_optional':body=f'return _map_accumulate[_Source[V], Identity[S.Value], _OptionalCombine[S], S.Error](Identity[S.Value](), _source(source^), Optional[S.Value]())'
        else:
            policy=f'_Last[{t}]' if name=='last' else f'_Count[{t}]';acc=f'Optional[{t}]()' if name=='last' else '0'
            body=f'return _map_accumulate[_Source[V], Identity[{t}], {policy}, Never](Identity[{t}](), _source(source^), {acc})'
        summary={'first':'Consume at most one element and return it, or None for empty input.','last':'Consume every remaining element and return the last, or None.','is_empty':'Consume at most one element and report whether none was present.','count':'Consume and count every remaining element; empty input returns zero.','contains':'Borrow candidates for native equality and stop at the first match.','to_non_empty_list':'Collect once into a checked NonEmptyList, returning None when empty.','combine_all_optional':'Combine left to right with a Semigroup; empty input returns None.'}[name]
        out+=emit(name,params,args,result,cond,body,summary,'The source is consumed without restarting. Values are moved or destroyed\nwithout requiring copies. Early exit destroys the unconsumed owner; no\nadditional value is pulled. Collection and full reductions require finite\ninput; count visits every element even when bounds give its length.',error,ind)
    for name in ['count_where','for_each','collect_fold']:
        for kind in ['pure','raising','library']:
            borrow=name=='count_where'; native=kind!='library';params=[]
            if native:params=[('P: AnyType' if borrow else f'A: {MD}'), f'R: {MD}', 'o: ImmOrigin'];t=f'downcast[P, {MD}]' if borrow else 'A'
            else:params=['C: BorrowCallable' if borrow else f'F: UnaryContract & {MD}'];t=f'downcast[C.Payload, {MD}]' if borrow else 'F.Arg'
            if mode=='free':params+=[f'V: {MD}']
            extras=['M: Monoid'] if name=='collect_fold' else []
            if native:
                e='E' if kind=='raising' else 'Never'
                if kind=='raising':extras+=[f'E: {MD}']
                bound=('_RaisingBorrowing[P, R, E]' if kind=='raising' else '_Borrowing[P, R]') if borrow else ('_RaisingUnary[A, R, E]' if kind=='raising' else '_Unary[A, R]')
                extras+=['F: '+bound]
                cb=f'_NativeBorrowRef[P, R, {e}, F, {kind=="raising"}, o]' if borrow else f'_NativeUnaryRef[A, R, {e}, F, {kind=="raising"}, o]'
                arg='ref[o] '+('predicate' if borrow else 'function')+': F';val=f'{cb}(Pointer(to='+('predicate' if borrow else 'function')+'))';cr='R'
            else:
                e='C.Failure' if borrow else 'F.Error';cb='C' if borrow else 'F';arg='var '+('predicate: C' if borrow else 'function: F');val='predicate^' if borrow else 'function^';cr='C.Result' if borrow else 'F.Out'
            if extras:params+=['//']+extras
            args=([arg,'var source: V'] if mode=='free' else ['deinit self',arg])
            result='Int' if borrow else 'NoneType' if name=='for_each' else 'M.Value'
            cond=it+'.Element == '+t+' and '+cr+' == '+('Bool' if borrow else 'NoneType' if name=='for_each' else 'Optional[M.Value]')
            error=e if name!='collect_fold' else 'M.Error' if kind=='pure' else 'E' if kind=='raising' else f'_CommonError[{e}, M.Error]'
            if name=='collect_fold' and kind=='raising':cond+=' and _ErrorCompatible[E, M.Error]'
            body=f'return _{name}'+(f'[M=M, E={error}]' if name=='collect_fold' else '')+f'({val}, {src})'
            summary={'count_where':'Count accepted candidates, borrowing each once; empty input returns zero.','for_each':'Move each element into a callback returning NoneType, then return None.','collect_fold':'Map to Optional monoid values, skip absence and combine present values in order.'}[name]
            out+=emit(name,params,args,result,cond,body,summary,'This is a consuming terminal. Native callbacks are borrowed in place;\nlibrary callbacks are consumed. Failure stops before the next pull and\nkeeps its exact native type, including callback StopIteration. Move-only\ninputs and results retain their origins; no intermediate collection is built.',error,ind,docs=kind=='pure')
    return out

def methods():return native_methods()+indexed('iter')+prefixes('iter')+terminals('iter')+branching('iter')


PARAMS.update({'U':'The callback result type, an exact Result for classification.'})
ARGS['buffer']='The required buffering policy; there is no implicit default.'

def branching(mode):
    out=''; ind='' if mode=='free' else '    '
    it='_Source[V]' if mode=='free' else 'Self.I'
    src='source^' if mode=='free' else 'self._iterator^'
    detail='Construction pulls nothing and each source item is classified once. Branches are move-only.\nUnbounded queues retain every pending value; BoundedFail yields Result elements,\ndiscards all queued values on overflow and gives each live branch one terminal Err.\nClose a branch to release its queue without draining upstream. Access is sequential;\nreentrant or overlapping access aborts before a second mutable state borrow.'
    for name in ['partition','partition_map']:
        ispart=name=='partition'
        for kind in ['thin','native','library']:
            params=([f'T: {MD}']+([] if ispart else [f'U: {MD}'])) if kind!='library' else (['C: BorrowCallable'] if ispart else [f'F: UnaryContract & {MD}'])
            if mode=='free':params+=[f'V: {MD}']
            params+=['P: _BufferPolicy']
            t='T' if kind!='library' else f'downcast[C.Payload, {MD}]' if ispart else 'F.Arg'
            u='U' if kind!='library' else 'F.Out'
            cb=('def(T) thin -> Bool' if ispart else 'def(var T) thin -> U') if kind=='thin' else ('C' if kind=='library' and ispart else 'F')
            if kind=='native':params+=['//', 'F: _LazyPredicate[T]' if ispart else 'F: _LazyUnary[T, U]']
            condition=f'{it}.Element == {t}'
            if ispart and kind=='library':condition+=' and C.Result == Bool and C.Failure == Never'
            if not ispart:condition+=f' and conforms_to({u}, _ResultType)'
            if not ispart and kind=='library':condition+=' and F.Error == Never and RepeatableUnary[F]'
            result=f'PartitionBranches[{t}, {it}, {cb}, P]' if ispart else f'PartitionMapBranches[{t}, {u}, {it}, {cb}, P]'
            args=['var '+('predicate' if ispart else 'function')+': '+cb]
            if mode=='free':args+=['var source: V']
            else:args.insert(0,'deinit self')
            args+=['*','var buffer: P']
            value=('predicate' if ispart else 'function')+('' if kind=='thin' else '^')
            if mode=='free':
                route=f'_Partition[{t}, {cb}]({value})' if ispart else f'_Classify[{t}, {u}, {cb}]({value})'
                a=t if ispart else f'downcast[{u}, _ResultType].Value'
                b=t if ispart else f'downcast[{u}, _ResultType].Error'
                body=f'return _branches[{a}, {b}](_source({src}), {route}, buffer^)'
            else:
                forward='[T=T'+('' if ispart else ', U=U')+']' if kind!='library' else ''
                body=f'return _{name}{forward}({value}, {src}, buffer=buffer^)'
            out+=emit(name,params,args,result,condition,body,'Lazily split accepted and rejected elements into independent iterators.' if ispart else 'Lazily route Result payloads into independent Ok and Err iterators.',detail,indent=ind,docs=kind=='thin')
    params=[f'A: {MD}',f'B: {MD}']+([f'V: {MD}'] if mode=='free' else [])+['P: _BufferPolicy']
    args=(['var source: V'] if mode=='free' else ['deinit self'])+['*','var buffer: P']
    body=f'return _branches[A, B](_source({src}), _Unzip[A, B](), buffer^)' if mode=='free' else f'return _unzip[A, B]({src}, buffer=buffer^)'
    out+=emit('unzip',params,args,f'UnzipBranches[A, B, {it}, P]',f'{it}.Element == Tuple[A, B]',body,'Lazily split native tuple fields, checking both queues before publishing either field.',detail,indent=ind)
    return out
